import{_ as e,c as r,o as i,ah as t}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"25、【無妄】 震下乾上","description":"橫渠易說 - 25、【無妄】 震下乾上","frontmatter":{"title":"25、【無妄】 震下乾上","description":"橫渠易說 - 25、【無妄】 震下乾上"},"headers":[],"relativePath":"classics/hengqu/027.md","filePath":"classics/hengqu/027.md"}'),h={name:"classics/hengqu/027.md"};function l(n,a,s,c,d,o){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_25、【無妄】-震下乾上" tabindex="-1">25、【無妄】 震下乾上 <a class="header-anchor" href="#_25、【無妄】-震下乾上" aria-label="Permalink to “25、【無妄】 震下乾上”">​</a></h1><h3 id="彖曰-無妄-剛自外來而為主於內-動而健-剛中而應-大亨以正-天之命也。-其匪正有眚-不利有攸往-無妄之往何之矣-天命不祐-行矣哉" tabindex="-1">彖曰：無妄，剛自外來而為主於內，動而健，剛中而應，大亨以正，天之命也。“其匪正有眚，不利有攸往”，無妄之往何之矣!天命不祐，行矣哉! <a class="header-anchor" href="#彖曰-無妄-剛自外來而為主於內-動而健-剛中而應-大亨以正-天之命也。-其匪正有眚-不利有攸往-無妄之往何之矣-天命不祐-行矣哉" aria-label="Permalink to “彖曰：無妄，剛自外來而為主於內，動而健，剛中而應，大亨以正，天之命也。“其匪正有眚，不利有攸往”，無妄之往何之矣!天命不祐，行矣哉!”">​</a></h3><p>無妄四德，無妄而後具四德也。其曰“匪正有眚”，對無妄雷行天動也，天動不妄，故曰“無妄”。天動不妄則物亦無妄，乾道變化各正性命也。 象曰：天下雷行，物與無妄，先王以茂對時，育萬物。 物因雷動，雷動不妄則物亦不妄，故曰“物與無妄”。育不以時，害莫甚焉。</p><h3 id="初九-無妄往吉。-象曰-無妄之往-得志也。" tabindex="-1">初九，無妄往吉。 象曰：無妄之往，得志也。 <a class="header-anchor" href="#初九-無妄往吉。-象曰-無妄之往-得志也。" aria-label="Permalink to “初九，無妄往吉。 象曰：無妄之往，得志也。”">​</a></h3><p>易所謂“得志”者，聖賢獲其願欲者也。得臣無家，堯之志也；貞吉升階，舜之志也。</p><h3 id="六二-不耕穫-不災畲-則利有攸往。-象曰-不耕穫-未富也。" tabindex="-1">六二，不耕穫，不災畲，則利有攸往。 象曰：“不耕穫”，未富也。 <a class="header-anchor" href="#六二-不耕穫-不災畲-則利有攸往。-象曰-不耕穫-未富也。" aria-label="Permalink to “六二，不耕穫，不災畲，則利有攸往。 象曰：“不耕穫”，未富也。”">​</a></h3><p>柔之為道不利遠者，能遠利不為物首則可，乘剛處實則兇。</p><h3 id="六三-無妄之災-或繫之牛-行人之得-邑人之災。-象曰-行人得牛-邑人災也。" tabindex="-1">六三，無妄之災，或繫之牛，行人之得，邑人之災。 象曰：行人得牛，邑人災也。 <a class="header-anchor" href="#六三-無妄之災-或繫之牛-行人之得-邑人之災。-象曰-行人得牛-邑人災也。" aria-label="Permalink to “六三，無妄之災，或繫之牛，行人之得，邑人之災。 象曰：行人得牛，邑人災也。”">​</a></h3><p>妄災之大，莫大於妄誅於人，以陰居陽，體躁而動，遷怒肆暴，災之甚者。系牛為說，緣耕穫 生詞。</p><h3 id="九四-可貞-無咎。-象曰-可貞無咎-固有之也。" tabindex="-1">九四，可貞，無咎。 象曰：“可貞無咎”，固有之也。 <a class="header-anchor" href="#九四-可貞-無咎。-象曰-可貞無咎-固有之也。" aria-label="Permalink to “九四，可貞，無咎。 象曰：“可貞無咎”，固有之也。”">​</a></h3><h3 id="九五-無妄之疾-勿藥有喜。-象曰-無妄之藥-不可試也。" tabindex="-1">九五，無妄之疾，勿藥有喜。 象曰：無妄之藥，不可試也。 <a class="header-anchor" href="#九五-無妄之疾-勿藥有喜。-象曰-無妄之藥-不可試也。" aria-label="Permalink to “九五，無妄之疾，勿藥有喜。 象曰：無妄之藥，不可試也。”">​</a></h3><p>體健居尊，得行其志，故以無妄為疾。“無妄之疾”，疾無妄之謂也，欲妄動而不敢妄，是則以無妄為疾者也，如孟子言“有法家拂士”，是疾無妄者也。以無妄為病而醫之，則妄之意遂矣，故曰“勿藥有喜”，又曰“不可試也”，言不可用藥治之。</p><h3 id="上九-無妄行-有眚-無攸利。-象曰-無妄之行-窮之災也。" tabindex="-1">上九，無妄行，有眚，無攸利。 象曰：無妄之行，窮之災也。 <a class="header-anchor" href="#上九-無妄行-有眚-無攸利。-象曰-無妄之行-窮之災也。" aria-label="Permalink to “上九，無妄行，有眚，無攸利。 象曰：無妄之行，窮之災也。”">​</a></h3><p>進而過中，是無妄而行也。</p>',14)])])}const m=e(h,[["render",l]]);export{_ as __pageData,m as default};
